 private static string formatstring = "{0:#,#.00}";
private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
AlphaWebReports.raporteUtil.shtoFiltra((XRTable)sender, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));

}

private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}

private void xrLabel66_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
 if (dtFunditBank == DateTime.Parse("01/01/0001 00:00:00"))
            {
                e.Result = "0";
            }
            else
            {
                TimeSpan dt = dtFunditBank - dtMaturimi;
                e.Result = dt.TotalDays.ToString();
            }
            e.Handled = true;
}

private void xrLabel66_SummaryReset(object sender, System.EventArgs e) {
  nr = 0;
            dtFunditBank = DateTime.MinValue;
}

private void xrLabel66_SummaryRowChanged(object sender, System.EventArgs e) {
{
            if (GetCurrentColumnValue("DATEDOKGJENDJEKF") != null && GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString() != "")
            {
                if (dtFunditBank < DateTime.Parse(GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString()) && GetCurrentColumnValue("IDKATDOK").ToString() == "4")
                    dtFunditBank = DateTime.Parse(GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString());
                if (nr == 0 && GetCurrentColumnValue("DTMATURIMI") != null && GetCurrentColumnValue("DTMATURIMI").ToString() != "")
                    dtMaturimi = DateTime.Parse(GetCurrentColumnValue("DTMATURIMI").ToString());
            }
            nr++;
	}
}

private void xrLabel65_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
 if (dtFunditCash == DateTime.Parse("01/01/0001 00:00:00"))
            {
                e.Result = "0";
            }
            else
            {
                TimeSpan dt = dtFunditCash - dtMaturimi;
                e.Result = dt.TotalDays.ToString();
            }
            e.Handled = true;
}

private void xrLabel65_SummaryReset(object sender, System.EventArgs e) {

            nr = 0;
            dtFunditCash = DateTime.MinValue;
}

private void xrLabel65_SummaryRowChanged(object sender, System.EventArgs e) {
 if (GetCurrentColumnValue("DATEDOKGJENDJEKF") != null && GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString() != "")
            {
                if (dtFunditCash < DateTime.Parse(GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString()) && GetCurrentColumnValue("IDKATDOK").ToString() == "3")
                    dtFunditCash = DateTime.Parse(GetCurrentColumnValue("DATEDOKGJENDJEKF").ToString());
                if (nr == 0 && GetCurrentColumnValue("DTMATURIMI") != null && GetCurrentColumnValue("DTMATURIMI").ToString() != "")
                    dtMaturimi = DateTime.Parse(GetCurrentColumnValue("DTMATURIMI").ToString());
            }
            nr++;
}

private void xrLabel3_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
shumaProgresiveBank = 0;
            shumaProgresiveCash = 0;
}

private void xrLabel17_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

          if (GetCurrentColumnValue("IDKATDOK") != null && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) == 2)
            {
                string llojDok = GetCurrentColumnValue("NIVELREGJISTRIMI").ToString();
                string nrDok = GetCurrentColumnValue("NRDOKGJENDJEKF").ToString();
                string idDok = GetCurrentColumnValue("IDDOKUMENTI").ToString();
                string url = AlphaWebReports.raporteUtil.ktheUrlDokumentiRaportKlientFurnitor( llojDok, idDok, nrDok, scopeID );
                if (url != "")
                {
                    xrLabel17.NavigateUrl = url;
                    xrLabel17.ForeColor = Color.SteelBlue;
                    xrLabel17.Target = "_self";
                }
            }
            if (GetCurrentColumnValue("CASH") != null && GetCurrentColumnValue("CASH").ToString() != "")
            {
                    vleftaCash = double.Parse(GetCurrentColumnValue("CASH").ToString());
            }
            if (GetCurrentColumnValue("BANK") != null && GetCurrentColumnValue("BANK").ToString() != "")
            {
                    vleftaBank = double.Parse(GetCurrentColumnValue("BANK").ToString());
            }}

private void xrLabel7_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

            if (GetCurrentColumnValue("IDKATDOK")!= null && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) != 3 && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) != 4 && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) != 10)
            {
                xrLabel7.Text = "";
                xrLabel8.Text = "";
                xrLabel9.Text = "";
                xrLabel13.Text = "";
                xrLabel14.Text = "";
                xrLabel21.Text = "";
            }
}

private void xrLabel14_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 if (GetCurrentColumnValue("IDKATDOK")!= null && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) == 3)
            {
                    shumaProgresiveCash += double.Parse(GetCurrentColumnValue("VLERA").ToString());
                xrLabel14.Text = String.Format(formatstring, shumaProgresiveCash);
            }
            else if (GetCurrentColumnValue("IDKATDOK")!= null && int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) == 4)
            {
                    shumaProgresiveBank += double.Parse(GetCurrentColumnValue("VLERA").ToString());
                xrLabel14.Text = String.Format(formatstring, shumaProgresiveBank);
            }
}

private void xrLabel21_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if (GetCurrentColumnValue("IDKATDOK") != null)
            {
                if (int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) == 3)
                {
                    xrLabel21.Text = String.Format(formatstring, vleftaCash - shumaProgresiveCash);
                }
                else if (int.Parse(GetCurrentColumnValue("IDKATDOK").ToString()) == 4)
                {
                    xrLabel21.Text = String.Format(formatstring, vleftaBank - shumaProgresiveBank);
                }
            }
}
